function readAsset(filePath) {
  const bytes = fs.readFileSync(filePath);
  return { json: JSON.parse(bytes.toString('utf8')), sha256: crypto.createHash('sha256').update(bytes).digest('hex') };
}
function wordCount(value) { return String(value || '').trim().split(/\s+/).filter(Boolean).length; }
function normalizeText(value) { return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().replace(/\s+/g, ' '); }
function tokenSet(value) { return new Set((normalizeText(value).match(/[a-z0-9]+/g) || []).filter((token) => token.length > 2)); }
function jaccardSimilarity(left, right) { const a = tokenSet(left); const b = tokenSet(right); let intersection = 0; for (const token of a) if (b.has(token)) intersection += 1; const union = a.size + b.size - intersection; return union ? intersection / union : 0; }
function validHttpsUrl(value) { try { return new URL(value).protocol === 'https:'; } catch (_) { return false; } }
function countBy(records, getter) { return records.reduce((counts, record) => { const key = String(getter(record)); counts[key] = (counts[key] || 0) + 1; return counts; }, {}); }
function referencesValid(records) { return Array.isArray(records) && records.length >= 3 && records.every((url) => validHttpsUrl(url) && allowedHosts.has(new URL(url).hostname.toLowerCase())); }
